\begin{itemchoice}
			\itemch Theo cách viết tập hợp dưới dạng khoảng, nửa khoảng thì $A = (-2; 5], B = (1; +\infty)$.
			\itemch $A \cap B = (1; 5]$.
			\itemch $A \cup B = (-2; +\infty)$.
			\itemch $A \cap B = (1; 5] \Rightarrow C_{\mathbb{R}}(A \cap B) = \mathbb{R} \setminus (1; 5] = (-\infty; 1] \cup (5; +\infty)$.
		\end{itemchoice}
